import os
from datetime import date, timedelta

d='/app/logs'
ref=date(2025,8,12)
sevs=('ERROR','WARNING','INFO')
periods=('today','last_7_days','last_30_days','month_to_date','total')

def in_period(p,dte):
    if p=='today':
        return dte==ref
    if p=='last_7_days':
        return ref - timedelta(days=6) <= dte <= ref
    if p=='last_30_days':
        return ref - timedelta(days=29) <= dte <= ref
    if p=='month_to_date':
        return dte.year==ref.year and dte.month==ref.month and dte<=ref
    if p=='total':
        return True
    return False

cnt={p:{s:0 for s in sevs} for p in periods}
alt={p:{s:0 for s in sevs} for p in periods}
files=0
badname=0
lines=0
mismatch=0
badlines=0
sev_all={s:0 for s in sevs}
filename_dates=[]
for name in sorted(os.listdir(d)):
    parts=name.split('_')
    if len(parts)<2 or not name.endswith('.log'):
        badname += 1
        continue
    dp=parts[0]
    if len(dp)!=10:
        badname += 1
        continue
    try:
        fd=date(int(dp[0:4]), int(dp[5:7]), int(dp[8:10]))
    except Exception:
        badname += 1
        continue
    files += 1
    filename_dates.append(fd)
    path=os.path.join(d,name)
    with open(path) as f:
        for line in f:
            line=line.strip()
            if not line:
                continue
            lines += 1
            toks=line.split()
            if len(toks)<3:
                badlines += 1
                continue
            lvl=toks[2].strip('[]')
            if lvl not in sevs:
                badlines += 1
                continue
            sev_all[lvl] += 1
            for p in periods:
                if in_period(p,fd):
                    cnt[p][lvl] += 1
            if len(line)>=10 and line[4]=='-' and line[7]=='-':
                try:
                    ld=date(int(line[0:4]), int(line[5:7]), int(line[8:10]))
                except Exception:
                    ld=None
            else:
                ld=None
            if ld is None:
                continue
            if ld != fd:
                mismatch += 1
            for p in periods:
                if in_period(p,ld):
                    alt[p][lvl] += 1

print('files', files, 'badname', badname, 'lines', lines, 'mismatch', mismatch, 'badlines', badlines)
print('total severities', sev_all)
if filename_dates:
    print('date range files min', min(filename_dates), 'max', max(filename_dates))
for p in periods:
    print(p, cnt[p])
print('ALT by line date')
for p in periods:
    print(p, alt[p])
PY
